using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Text;using SargasPC;
public sealed class CaseReviewWindow:Form {
 readonly ListBox items=new ListBox();readonly ComboBox files=new ComboBox();readonly TextBox detail=new TextBox();readonly Button refresh=new Button(),pick=new Button(),check=new Button(),quarantine=new Button(),restore=new Button(),cancel=new Button();CaseReview.Case selected;bool busy;
 public CaseReviewWindow(){Text="SARGON — paslaugos radinių valdymas";Width=1080;Height=760;MinimumSize=new Size(980,680);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterScreen;
  var grid=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=5,ColumnCount=1,Padding=new Padding(14)};grid.RowStyles.Add(new RowStyle(SizeType.Absolute,65));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,120));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,45));grid.RowStyles.Add(new RowStyle(SizeType.Percent,100));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,105));var note=new Label{Dock=DockStyle.Fill,Text="Istorinis radinys nėra dabartinio failo būsena. Prieš karantiną atliekama nauja vietinio variklio patikra. Kopijos priklauso šį langą paleidusiai paskyrai. Failai iš šio lango nepaleidžiami."};items.Dock=DockStyle.Fill;files.Dock=DockStyle.Fill;files.DropDownStyle=ComboBoxStyle.DropDownList;detail.Dock=DockStyle.Fill;detail.Multiline=true;detail.ReadOnly=true;detail.ScrollBars=ScrollBars.Both;detail.WordWrap=false;var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};Button[] buttons={refresh,pick,check,quarantine,restore,cancel};string[] labels={"Atnaujinti sąrašą","Pasirinkti failą…","Patikrinti iš naujo","Į karantiną","Atkurti į naują vietą…","Atšaukti veiksmą"};for(int i=0;i<buttons.Length;i++){buttons[i].Text=labels[i];buttons[i].Width=225;buttons[i].Height=40;actions.Controls.Add(buttons[i]);}grid.Controls.Add(note,0,0);grid.Controls.Add(items,0,1);grid.Controls.Add(files,0,2);grid.Controls.Add(detail,0,3);grid.Controls.Add(actions,0,4);Controls.Add(grid);cancel.Enabled=false;
  refresh.Click+=(s,e)=>Reload();items.SelectedIndexChanged+=(s,e)=>SelectRecord();pick.Click+=(s,e)=>{if(selected==null)return;using(var d=new OpenFileDialog{InitialDirectory=Directory.Exists(selected.Directory)?selected.Directory:"",CheckFileExists=true})if(d.ShowDialog(this)==DialogResult.OK){files.Items.Add(d.FileName);files.SelectedIndex=files.Items.Count-1;}};check.Click+=(s,e)=>RunAction("check",null);quarantine.Click+=(s,e)=>{if(MessageBox.Show(this,"Karantinuoti tik jei nauja patikra patvirtins tikrą variklio radinį? Galimi klaidingi perspėjimai; prieš šalinimą tikrinama atkuriama kopija.","Patvirtinti veiksmą",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)==DialogResult.Yes)RunAction("quarantine",null);};restore.Click+=(s,e)=>{if(selected==null)return;using(var d=new SaveFileDialog{FileName="atkurtas_failas.bin",OverwritePrompt=true})if(d.ShowDialog(this)==DialogResult.OK)RunAction("restore",d.FileName);};cancel.Click+=(s,e)=>CaseReview.Cancel();Shown+=(s,e)=>Reload();FormClosing+=(s,e)=>{if(busy){e.Cancel=true;CaseReview.Cancel();detail.AppendText("\r\nAtšaukiama. Palaukite veiksmo ir žurnalo įrašymo pabaigos.");}};
 }
 string Root{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SARGONService","Private","cases");}}
 void Reload(){if(busy)return;items.Items.Clear();selected=null;files.Items.Clear();try{if(!Directory.Exists(Root)){detail.Text="Prieinamų paslaugos radinių nėra. Tikri radiniai šiame lange atsiras įdiegus paslaugą ir jai juos užfiksavus.";return;}FolderMonitor.NoLinks(Root);foreach(string path in Directory.EnumerateFiles(Root,"*.json").Take(500)){FolderMonitor.NoLinks(path);var c=Data.Read<CaseReview.Case>(path,131072);if(c!=null&&c.Id!=null&&c.Id.Length==32&&c.Id.All(Uri.IsHexDigit)&&Path.GetFileNameWithoutExtension(path)==c.Id){items.Items.Add(c.Id+" — "+Data.Clean(c.State));}}if(items.Items.Count>0)items.SelectedIndex=0;}catch(Exception e){detail.Text="Radinių sąrašas nepatvirtintas: "+Data.Diagnostic(e);}}
 void SelectRecord(){if(busy||items.SelectedItem==null)return;try{string id=items.SelectedItem.ToString().Substring(0,32);selected=Data.Read<CaseReview.Case>(Path.Combine(Root,id+".json"),131072);files.Items.Clear();detail.Text=Data.CleanLog(selected.Report)+"\r\n\r\nPASKUTINĖ PERŽIŪRA\r\n"+Data.CleanLog(selected.Review);if(!string.IsNullOrEmpty(selected.ReviewedFile))files.Items.Add(selected.ReviewedFile);foreach(string line in (selected.Report??"").Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){if(!line.EndsWith(" FOUND",StringComparison.Ordinal))continue;int split=line.LastIndexOf(": ",StringComparison.Ordinal);if(split<0)continue;string path=line.Substring(0,split);try{if(Path.IsPathRooted(path)&&string.Equals(Path.GetDirectoryName(Path.GetFullPath(path)).TrimEnd(Path.DirectorySeparatorChar),Path.GetFullPath(selected.Directory).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)&&!files.Items.Contains(path))files.Items.Add(path);}catch(ArgumentException){}}if(files.Items.Count>0)files.SelectedIndex=0;}catch(Exception e){selected=null;detail.Text="Radinys neperskaitytas: "+Data.Diagnostic(e);}}
 async void RunAction(string action,string destination){if(busy||selected==null)return;string file=files.SelectedItem as string;if(action!="restore"&&file==null){MessageBox.Show(this,"Pasirinkite konkretų radinio failą.");return;}string id=selected.Id;var args=action=="restore"?new[]{"--case",id,"--action",action,"--destination",destination}:new[]{"--case",id,"--action",action,"--file",file};busy=true;foreach(var b in new[]{refresh,pick,check,quarantine,restore})b.Enabled=false;items.Enabled=files.Enabled=false;cancel.Enabled=true;try{string output=await Task.Run(()=>{var text=new StringBuilder();using(var writer=new StringWriter(text)){TextWriter previous=Console.Out;Console.SetOut(writer);try{int code=CaseReview.Execute(args);writer.WriteLine("Baigties kodas: "+code);}finally{Console.SetOut(previous);}}return text.ToString();});detail.Text=output;}catch(Exception e){detail.Text="Veiksmas nepatvirtintas: "+Data.Diagnostic(e);}finally{busy=false;foreach(var b in new[]{refresh,pick,check,quarantine,restore})b.Enabled=true;items.Enabled=files.Enabled=true;cancel.Enabled=false;}}
}
